def is_rotated_v1(first: str, second: str) -> bool:
    if len(first) != len(second):
        return False
    if len(first) == 0:
        return True
    for offset in range(len(first)):
        if all((first[(offset + index) % len(first)] == second[index] for index in range(len(first)))):
            return True
    return False

def prime_sieve_eratosthenes(num: int) -> list[int]:
    if num <= 0:
        raise ValueError('Input must be a positive integer')
    primes = [True] * (num + 1)
    p = 2
    while p * p <= num:
        if primes[p]:
            for i in range(p * p, num + 1, p):
                primes[i] = False
        p += 1
    return [prime for prime in range(2, num + 1) if primes[prime]]

def count_paths(rows: int, cols: int) -> int:
    if rows < 1 or cols < 1:
        return -1
    count = [[None for _ in range(cols)] for _ in range(rows)]
    for i in range(cols):
        count[0][i] = 1
    for j in range(rows):
        count[j][0] = 1
    for i in range(1, rows):
        for j in range(1, cols):
            count[i][j] = count[i - 1][j] + count[i][j - 1]
    return count[rows - 1][cols - 1]

def solution(limit: int=1000000) -> int:
    limit = limit + 1
    frequency = [0] * limit
    for first_term in range(1, limit):
        for n in range(first_term, limit, first_term):
            common_difference = first_term + n / first_term
            if common_difference % 4:
                continue
            common_difference /= 4
            if first_term > common_difference and first_term < 4 * common_difference:
                frequency[n] += 1
    count = sum((1 for x in frequency[1:limit] if x == 10))
    return count

def minimum_cost_path(matrix: list[list[int]]) -> int:
    for i in range(1, len(matrix[0])):
        matrix[0][i] += matrix[0][i - 1]
    for i in range(1, len(matrix)):
        matrix[i][0] += matrix[i - 1][0]
    for i in range(1, len(matrix)):
        for j in range(1, len(matrix[0])):
            matrix[i][j] += min(matrix[i - 1][j], matrix[i][j - 1])
    return matrix[-1][-1]

def is_luhn(string: str) -> bool:
    check_digit: int
    _vector: list[str] = list(string)
    (__vector, check_digit) = (_vector[:-1], int(_vector[-1]))
    vector: list[int] = [int(digit) for digit in __vector]
    vector.reverse()
    for (i, digit) in enumerate(vector):
        if i & 1 == 0:
            doubled: int = digit * 2
            if doubled > 9:
                doubled -= 9
            check_digit += doubled
        else:
            check_digit += digit
    return check_digit % 10 == 0

def bead_sort(sequence: list) -> list:
    if any((not isinstance(x, int) or x < 0 for x in sequence)):
        raise TypeError('Sequence must be list of non-negative integers')
    for _ in range(len(sequence)):
        for (i, (rod_upper, rod_lower)) in enumerate(zip(sequence, sequence[1:])):
            if rod_upper > rod_lower:
                sequence[i] -= rod_upper - rod_lower
                sequence[i + 1] += rod_upper - rod_lower
    return sequence

def geometric_series(nth_term: float, start_term_a: float, common_ratio_r: float) -> list[float]:
    if not all((nth_term, start_term_a, common_ratio_r)):
        return []
    series: list[float] = []
    power = 1
    multiple = common_ratio_r
    for _ in range(int(nth_term)):
        if not series:
            series.append(start_term_a)
        else:
            power += 1
            series.append(float(start_term_a * multiple))
            multiple = pow(float(common_ratio_r), power)
    return series

def sum_digits(num: int) -> int:
    digit_sum = 0
    while num > 0:
        digit_sum += num % 10
        num //= 10
    return digit_sum

def fwht_and(sequence: list[int], inverse: bool=False) -> list[int]:
    sequence_length = len(sequence)
    if sequence_length == 0 or sequence_length & sequence_length - 1 != 0:
        raise ValueError('Length of sequence must be a positive power of 2.')
    result = list(sequence)
    half_block = 1
    while half_block < sequence_length:
        block_size = half_block * 2
        for block_start in range(0, sequence_length, block_size):
            for offset in range(half_block):
                left_index = block_start + offset
                right_index = left_index + half_block
                if not inverse:
                    result[left_index] += result[right_index]
                else:
                    result[left_index] -= result[right_index]
        half_block *= 2
    return result

def bin_to_decimal(bin_string: str) -> int:
    bin_string = str(bin_string).strip()
    if not bin_string:
        raise ValueError('Empty string was passed to the function')
    is_negative = bin_string[0] == '-'
    if is_negative:
        bin_string = bin_string[1:]
    if not all((char in '01' for char in bin_string)):
        raise ValueError('Non-binary value was passed to the function')
    decimal_number = 0
    for char in bin_string:
        decimal_number = 2 * decimal_number + int(char)
    return -decimal_number if is_negative else decimal_number

def compute_bridges(graph: dict[int, list[int]]) -> list[tuple[int, int]]:
    id_ = 0
    n = len(graph)
    low = [0] * n
    visited = [False] * n

    def dfs(at, parent, bridges, id_) -> None:
        visited[at] = True
        low[at] = id_
        id_ += 1
        for to in graph[at]:
            if to == parent:
                pass
            elif not visited[to]:
                dfs(to, at, bridges, id_)
                low[at] = min(low[at], low[to])
                if id_ <= low[to]:
                    bridges.append((at, to) if at < to else (to, at))
            else:
                low[at] = min(low[at], low[to])
    bridges: list[tuple[int, int]] = []
    for i in range(n):
        if not visited[i]:
            dfs(i, -1, bridges, id_)
    return bridges

def find_primitive(modulus: int) -> int | None:
    for r in range(1, modulus):
        li = []
        for x in range(modulus - 1):
            val = pow(r, x, modulus)
            if val in li:
                break
            li.append(val)
        else:
            return r
    return None

def longest_increasing_subsequence_optimized2(sequence: list[int]) -> int:
    length = len(sequence)
    tree = [0] * (length << 2)
    sorted_seq = sorted(((x, -i) for (i, x) in enumerate(sequence)))

    def _update(pos: int, left: int, right: int, target: int, vertex: int) -> None:
        if left == right:
            tree[pos] = vertex
            return
        mid = left + right >> 1
        if target <= mid:
            _update(pos << 1, left, mid, target, vertex)
        else:
            _update(pos << 1 | 1, mid + 1, right, target, vertex)
        tree[pos] = max(tree[pos << 1], tree[pos << 1 | 1])

    def _get_max(pos: int, left: int, right: int, start: int, end: int) -> int:
        if left > end or right < start:
            return 0
        if left >= start and right <= end:
            return tree[pos]
        mid = left + right >> 1
        return max(_get_max(pos << 1, left, mid, start, end), _get_max(pos << 1 | 1, mid + 1, right, start, end))
    ans = 0
    for tup in sorted_seq:
        i = -tup[1]
        cur = _get_max(1, 0, length - 1, 0, i - 1) + 1
        ans = max(ans, cur)
        _update(1, 0, length - 1, i, cur)
    return ans

def check_valid(sig, args, kwargs):
    (num_pos_only, func, keyword_exclude, sigspec) = sig
    if len(args) < num_pos_only:
        return False
    if keyword_exclude:
        kwargs = dict(kwargs)
        for item in keyword_exclude:
            kwargs.pop(item, None)
    try:
        func(*args, **kwargs)
        return True
    except TypeError:
        return False

def is_sorted(head: object | None) -> bool:
    if not head:
        return True
    current = head
    while current.next:
        if current.val > current.next.val:
            return False
        current = current.next
    return True

def find_narcissistic_numbers(limit: int) -> list[int]:
    if limit <= 0:
        return []
    narcissistic_nums = []
    power_cache: dict[tuple[int, int], int] = {}

    def get_digit_power(digit: int, power: int) -> int:
        if (power, digit) not in power_cache:
            power_cache[power, digit] = digit ** power
        return power_cache[power, digit]
    for number in range(limit):
        num_digits = len(str(number))
        remaining = number
        digit_sum = 0
        while remaining > 0:
            digit = remaining % 10
            digit_sum += get_digit_power(digit, num_digits)
            remaining //= 10
        if digit_sum == number:
            narcissistic_nums.append(number)
    return narcissistic_nums

def merge_sorted_arrays(nums1: list[int], nums2: list[int]) -> list[int]:
    for nums in (nums1, nums2):
        if list(nums) != sorted(nums):
            msg = f'nums = {nums!r} is not sorted'
            raise ValueError(msg)
    if not nums1:
        return nums2
    if not nums2:
        return nums1
    (i, j) = (0, 0)
    merged = []
    while i < len(nums1) and j < len(nums2):
        if nums1[i] <= nums2[j]:
            merged.append(nums1[i])
            i += 1
        else:
            merged.append(nums2[j])
            j += 1
    merged.extend(nums1[i:])
    merged.extend(nums2[j:])
    return merged

def sentinel_linear_search(sequence, target):
    sequence.append(target)
    index = 0
    while sequence[index] != target:
        index += 1
    sequence.pop()
    if index == len(sequence):
        return None
    return index

def array_sum_combinations(array_a: list[int], array_b: list[int], array_c: list[int], target: int) -> list[list[int]]:
    arrays = [array_a, array_b, array_c]

    def _is_complete(constructed_so_far: list[int]) -> tuple[bool, bool]:
        total = sum(constructed_so_far)
        should_stop = total >= target or len(constructed_so_far) >= 3
        reached_target = total == target and len(constructed_so_far) == 3
        return (should_stop, reached_target)

    def _get_candidates(constructed_so_far: list[int]) -> list[int]:
        return arrays[len(constructed_so_far)]

    def _backtrack(constructed_so_far: list[int] | None=None, result: list[list[int]] | None=None) -> None:
        if constructed_so_far is None:
            constructed_so_far = []
        if result is None:
            result = []
        (should_stop, reached_target) = _is_complete(constructed_so_far)
        if should_stop:
            if reached_target:
                result.append(constructed_so_far)
            return
        candidates = _get_candidates(constructed_so_far)
        for candidate in candidates:
            constructed_so_far.append(candidate)
            _backtrack(constructed_so_far[:], result)
            constructed_so_far.pop()
    result: list[list[int]] = []
    _backtrack([], result)
    return result

def solution(limit=28123):
    sum_divs = [1] * (limit + 1)
    for i in range(2, int(limit ** 0.5) + 1):
        sum_divs[i * i] += i
        for k in range(i + 1, limit // i + 1):
            sum_divs[k * i] += k + i
    abundants = set()
    res = 0
    for n in range(1, limit + 1):
        if sum_divs[n] > n:
            abundants.add(n)
        if not any((n - a in abundants for a in abundants)):
            res += n
    return res

def _count_cross_inversions(p: list[int], q: list[int]) -> tuple[list[int], int]:
    r = []
    i = j = num_inversion = 0
    while i < len(p) and j < len(q):
        if p[i] > q[j]:
            num_inversion += len(p) - i
            r.append(q[j])
            j += 1
        else:
            r.append(p[i])
            i += 1
    if i < len(p):
        r.extend(p[i:])
    else:
        r.extend(q[j:])
    return (r, num_inversion)

def decimal_to_binary_iterative(num: int) -> str:
    if isinstance(num, float):
        raise TypeError("'float' object cannot be interpreted as an integer")
    if isinstance(num, str):
        raise TypeError("'str' object cannot be interpreted as an integer")
    if num == 0:
        return '0b0'
    negative = False
    if num < 0:
        negative = True
        num = -num
    binary: list[int] = []
    while num > 0:
        binary.insert(0, num % 2)
        num >>= 1
    if negative:
        return '-0b' + ''.join((str(e) for e in binary))
    return '0b' + ''.join((str(e) for e in binary))

def word_break(word: str, word_dict: set[str]) -> bool:
    dp_array = [False] * (len(word) + 1)
    dp_array[0] = True
    for i in range(1, len(word) + 1):
        for j in range(0, i):
            if dp_array[j] and word[j:i] in word_dict:
                dp_array[i] = True
                break
    return dp_array[-1]

def perfect(number: int) -> bool:
    if not isinstance(number, int):
        raise ValueError('number must be an integer')
    if number <= 0:
        return False
    return sum((i for i in range(1, number // 2 + 1) if number % i == 0)) == number

def modular_exponential(base: int, power: int, mod: int):
    if power < 0:
        return -1
    base %= mod
    result = 1
    while power > 0:
        if power & 1:
            result = result * base % mod
        power = power >> 1
        base = base * base % mod
    return result

def fibonacci(n: int) -> int:
    if n == 1 or not isinstance(n, int):
        return 0
    elif n == 2:
        return 1
    else:
        sequence = [0, 1]
        for i in range(2, n + 1):
            sequence.append(sequence[i - 1] + sequence[i - 2])
        return sequence[n]

def get_longest_non_repeat_v2(string: str) -> tuple[int, str]:
    if string is None:
        return (0, '')
    substring = ''
    (start, max_length) = (0, 0)
    used_char = {}
    for (index, char) in enumerate(string):
        if char in used_char and start <= used_char[char]:
            start = used_char[char] + 1
        elif index - start + 1 > max_length:
            max_length = index - start + 1
            substring = string[start:index + 1]
        used_char[char] = index
    return (max_length, substring)

def binary_gap(number: int) -> int:
    last_one_position = None
    longest_gap = 0
    index = 0
    while number != 0:
        if number & 1:
            if last_one_position is not None:
                longest_gap = max(longest_gap, index - last_one_position)
            last_one_position = index
        index += 1
        number >>= 1
    return longest_gap

def solve(nums: list[int], goal: int, depth: int) -> bool:
    if len(nums) > depth:
        return False
    for el in nums:
        if el + nums[-1] == goal:
            return True
        nums.append(el + nums[-1])
        if solve(nums=nums, goal=goal, depth=depth):
            return True
        del nums[-1]
    return False

def solve(digit: int, prev1: int, prev2: int, sum_max: int, first: bool, cache: dict[str, int]) -> int:
    if digit == 0:
        return 1
    cache_str = f'{digit},{prev1},{prev2}'
    if cache_str in cache:
        return cache[cache_str]
    comb = 0
    for curr in range(sum_max - prev1 - prev2 + 1):
        if first and curr == 0:
            continue
        comb += solve(digit=digit - 1, prev1=curr, prev2=prev1, sum_max=sum_max, first=False, cache=cache)
    cache[cache_str] = comb
    return comb

def legendre_symbol(residue: int, prime: int) -> int:
    if prime <= 2 or prime % 2 == 0:
        raise ValueError('prime must be an odd prime')
    symbol = pow(residue % prime, (prime - 1) // 2, prime)
    return -1 if symbol == prime - 1 else symbol
